// The text of `doc-sources.generated.ts` for a set of Markdown sources: one place that defines the bundle, used by
// `npm run docs:bundle` to write it and by the guard test to compare it with the folder.

/** The generated module's source for the given Markdown files by slug. */
export function renderDocSourcesModule(sources: Readonly<Record<string, string>>): string {
  const entries = Object.entries(sources).map(([slug, markdown]) => `  ${JSON.stringify(slug)}: ${JSON.stringify(markdown)},`);
  return [
    "// Generated by `npm run docs:bundle` from content/docs/*.md. Do not edit: change the Markdown and run it again.",
    "export const DOC_SOURCES: Readonly<Record<string, string>> = {",
    ...entries,
    "};",
    "",
  ].join("\n");
}
